//! 📦️ Caller-retained encoder allocation slot.
use crate::{NativeAllocationFailure,ValueError,ValueRefusalKind};
use super::NativeEncodeControl;
fn reserve_vector<T>(output:&mut Vec<T>,layout:std::alloc::Layout,count:usize,bytes:usize,marker:&mut Option<usize>)->Result<(),ValueError>{let pointer=unsafe{std::alloc::alloc(layout)}.cast::<T>();if pointer.is_null(){*marker=Some(0);return Err(ValueError::literal(ValueRefusalKind::AllocationFailed,"native collection allocation failed"))}*output=unsafe{Vec::from_raw_parts(pointer,0,count)};*marker=Some(bytes);Ok(())}
fn reserve_text(output:&mut String,layout:std::alloc::Layout,bytes:usize,marker:&mut Option<usize>)->Result<(),ValueError>{let pointer=unsafe{std::alloc::alloc(layout)};if pointer.is_null(){*marker=Some(0);return Err(ValueError::literal(ValueRefusalKind::AllocationFailed,"native text allocation failed"))}*output=unsafe{String::from_utf8_unchecked(Vec::from_raw_parts(pointer,0,bytes))};*marker=Some(bytes);Ok(())}
impl NativeEncodeControl<'_>{
 /// 🫴️ Reserves into the original vector and retains its actual marker and parent progress.
 pub fn allocate_vec_into<T>(&mut self,count:usize,output:&mut Vec<T>,actual:&mut Option<usize>,progress:&mut Option<super::NativeEncodeAllocationProgress>)->Result<bool,NativeAllocationFailure>{
  let prior=progress.as_ref().map_or(self.owned_bytes(),|state|state.request().owned_bytes);let Some(bytes)=count.checked_mul(std::mem::size_of::<T>()).filter(|bytes|*bytes<=isize::MAX as usize)else{return Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"native collection size overflow").into())};if !output.is_empty(){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"native vector owner is not empty").into())}if bytes==0&&progress.is_none(){return Ok(true)}let layout=std::alloc::Layout::array::<T>(count).map_err(|_|NativeAllocationFailure::from(ValueError::literal(ValueRefusalKind::OwnershipLimit,"native collection layout overflow")))?;let outcome=if let Some(state)=progress.as_mut(){if state.request().bytes!=bytes{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"native vector request changed").into())}if state.operation_started(){let Some(marker)=*actual else{return Ok(false)};let retained=output.capacity().checked_mul(std::mem::size_of::<T>()).ok_or_else(||NativeAllocationFailure::from(ValueError::literal(ValueRefusalKind::InvariantViolated,"native vector extent overflow")))?;if retained!=marker{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"native vector marker changed").into())}if !self.settle_allocation_progress(state,Some(marker)).map_err(NativeAllocationFailure::from)?{return Ok(false)}Some(progress.take().expect("settled allocation progress").into_outcome().ok().expect("settled allocation outcome"))}else{if actual.is_some()||(std::mem::size_of::<T>()!=0&&output.capacity()!=0){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"unstarted native vector owns a physical effect").into())}self.continue_allocation_effect(actual,progress,&mut |marker,_work|reserve_vector(output,layout,count,bytes,marker).map(|()|true)).map_err(NativeAllocationFailure::from)?}}else{if actual.is_some()||(std::mem::size_of::<T>()!=0&&output.capacity()!=0){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"native allocation requires empty owner and marker").into())}self.allocate_effect(bytes,actual,progress,&mut |marker,_work|reserve_vector(output,layout,count,bytes,marker).map(|()|true)).map_err(NativeAllocationFailure::from)?};match outcome{None=>Ok(false),Some(outcome)=>match outcome.into_allocation_failure(prior){Some(failure)=>Err(failure),None=>Ok(true)}}
 }
 /// 🔤️ Reserves text backing in the original slot with the same retained marker and parent progress.
 pub fn reserve_text_into(&mut self,bytes:usize,output:&mut String,actual:&mut Option<usize>,progress:&mut Option<super::NativeEncodeAllocationProgress>)->Result<bool,NativeAllocationFailure>{
  let prior=progress.as_ref().map_or(self.owned_bytes(),|state|state.request().owned_bytes);if bytes>isize::MAX as usize{return Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"native text size overflow").into())}if !output.is_empty(){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"native text owner is not empty").into())}if bytes==0&&progress.is_none(){return Ok(true)}let layout=std::alloc::Layout::array::<u8>(bytes).map_err(|_|NativeAllocationFailure::from(ValueError::literal(ValueRefusalKind::OwnershipLimit,"native text layout overflow")))?;let outcome=if let Some(state)=progress.as_mut(){if state.request().bytes!=bytes{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"native text request changed").into())}if state.operation_started(){let Some(marker)=*actual else{return Ok(false)};if output.capacity()!=marker{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"native text marker changed").into())}if !self.settle_allocation_progress(state,Some(marker)).map_err(NativeAllocationFailure::from)?{return Ok(false)}Some(progress.take().expect("settled allocation progress").into_outcome().ok().expect("settled allocation outcome"))}else{if actual.is_some()||output.capacity()!=0{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"unstarted native text owns a physical effect").into())}self.continue_allocation_effect(actual,progress,&mut |marker,_work|reserve_text(output,layout,bytes,marker).map(|()|true)).map_err(NativeAllocationFailure::from)?}}else{if actual.is_some()||output.capacity()!=0{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"native allocation requires empty owner and marker").into())}self.allocate_effect(bytes,actual,progress,&mut |marker,_work|reserve_text(output,layout,bytes,marker).map(|()|true)).map_err(NativeAllocationFailure::from)?};match outcome{None=>Ok(false),Some(outcome)=>match outcome.into_allocation_failure(prior){Some(failure)=>Err(failure),None=>Ok(true)}}
 }
}

